// isCodexSystemContent returns true for content blocks that are system-injected
// rather than user-authored.
func isCodexSystemContent(text string) bool {
	prefixes := []string{
		"<permissions",
		"<collaboration_mode>",
		"<skills_instructions>",
		"<environment_context>",
		"<turn_aborted>",
		"# AGENTS.md",
	}
	for _, p := range prefixes {
		if len(text) >= len(p) && text[:len(p)] == p {
			return true
		}
	}
	return false
}

