package cli

import (
	"os"
	"path/filepath"
	"strings"
	"testing"

	codexagent "github.com/entireio/cli/cmd/entire/cli/agent/codex"
	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/textutil"
)

// oldFilter = the filter as written on this branch before the follow-up fixes.
func oldFilter(t string) bool {
	tr := strings.TrimSpace(t)
	return strings.HasPrefix(tr, "# AGENTS.md instructions for ") ||
		strings.HasPrefix(tr, "<environment_context>") ||
		(strings.Contains(tr, "<INSTRUCTIONS>") && strings.Contains(tr, "AGENTS.md instructions"))
}

func TestZZBeforeAfter(t *testing.T) {
	root := filepath.Join(os.Getenv("HOME"), ".codex", "sessions")
	ag := codexagent.NewCodexAgent()
	ex, _ := agent.AsPromptExtractor(ag)
	var n, mainLeak, branchLeak, nowLeak, noGenuine int
	_ = filepath.Walk(root, func(p string, fi os.FileInfo, err error) error {
		if err != nil || fi.IsDir() || !strings.HasSuffix(p, ".jsonl") {
			return nil
		}
		prompts, perr := ex.ExtractPrompts(p, 0)
		if perr != nil || len(prompts) == 0 {
			return nil
		}
		n++
		// main: prompts[0], unfiltered
		if textutil.IsInjectedPrompt(prompts[0]) {
			mainLeak++
		}
		// branch as merged: first non-injected per oldFilter, else prompts[0]
		pick := ""
		for _, q := range prompts {
			if strings.TrimSpace(q) != "" && !oldFilter(q) {
				pick = q
				break
			}
		}
		if pick == "" {
			pick = prompts[0]
		}
		if textutil.IsInjectedPrompt(pick) {
			branchLeak++
		}
		// now
		anyGenuine := false
		for _, q := range prompts {
			if strings.TrimSpace(q) != "" && !textutil.IsInjectedPrompt(q) {
				anyGenuine = true
				break
			}
		}
		if !anyGenuine {
			noGenuine++
			nowLeak++
		}
		return nil
	})
	t.Logf("rollouts=%d", n)
	t.Logf("  main (no filter)      : %d titled with injected content", mainLeak)
	t.Logf("  branch as merged      : %d", branchLeak)
	t.Logf("  with follow-up fixes  : %d  (all %d are sessions with NO genuine prompt -> fallback is correct)", nowLeak, noGenuine)
}
EOF
